    question: '什么是I/O系统？它由哪些部分组成？',
    answer: `## I/O系统概述

**I/O系统**是计算机系统中负责主机与外部设备之间信息交换的子系统。

## 组成部分

1. **外部设备**：输入设备（键盘、鼠标）、输出设备（显示器、打印机）、外存设备（硬盘、SSD）
2. **I/O接口**：连接主机与外设的逻辑电路，完成数据缓冲、电平转换、时序匹配
3. **I/O控制方式**：程序查询、程序中断、DMA、通道方式
4. **I/O总线**：连接各部件的公共通路

## 主要功能

- 完成主机与外设间的数据传送
- 实现数据格式的转换
- 协调主机与外设的速度差异
- 向CPU报告外设状态

> I/O系统是计算机与人交互的桥梁，其性能直接影响系统整体性能。`,
