    answer: `## 程序查询方式

CPU通过执行程序不断查询外设状态，等待外设就绪后进行数据交换。

## 工作流程

1. CPU向I/O接口发出命令，启动外设
2. CPU循环读取状态寄存器，判断外设是否就绪
3. 外设就绪后，CPU执行数据传送
4. 重复上述过程直至数据传送完成

## 优缺点

**优点**：
- 硬件简单，不需要复杂的接口电路
- 控制程序容易实现

**缺点**：
- CPU与外设串行工作，CPU利用率低
- 大量时间花在等待上，无法做其他工作
- 实时性差，无法及时响应多个外设

> 程序查询是最简单的I/O方式，适合低速、少量的外设控制。`,
