    answer: `## DMA方式原理

**DMA（直接存储器访问）**由DMA控制器直接控制外设与内存之间的数据交换，不需要CPU干预。

## 解决的问题

程序中断方式每个数据都要中断CPU，对于高速设备（磁盘、网卡）而言：
- 中断处理开销过大
- CPU频繁被打断，效率低
- 数据容易丢失

DMA通过让出总线控制权，由DMA控制器独立完成数据传送。

## 基本流程

1. CPU向DMA控制器发送命令（读/写、地址、数据量）
2. DMA控制器请求总线使用权
3. DMA控制器接管总线，直接在内存与外设间传送数据
4. 传送完成后DMA向CPU发中断信号

> DMA实现了CPU与外设真正意义上的并行工作。`,
