    question: '外设的编址方式有哪两种？各有什么特点？',
    answer: `## 两种外设编址方式

### 1. 统一编址（存储器映射编址）

I/O端口与内存单元共用同一地址空间。

- 优点：不需要专门的I/O指令，所有访存指令都可访问I/O
- 缺点：占用内存地址空间，译码电路复杂
- 代表：ARM、MIPS等RISC架构

### 2. 独立编址（I/O映射编址）

I/O端口有独立的地址空间，与内存分开。

- 优点：不占用内存空间，译码简单
- 缺点：需要专门的I/O指令（如IN、OUT）
- 代表：x86架构

## 对比

| 项目 | 统一编址 | 独立编址 |
|------|---------|---------|
| 地址空间 | 共享 | 独立 |
| 专用指令 | 不需要 | 需要 |
| 寻址方式 | 丰富 | 单一 |
| 译码复杂度 | 高 | 低 |

> 现代嵌入式系统多采用统一编址，便于统一管理。`,
