    answer: `## 中断系统功能

中断系统是计算机实现中断处理的硬件和软件的总称。

## 基本功能

1. **中断请求检测**：能检测各中断源的中断请求信号
2. **中断响应判优**：多个中断同时发生时，按优先级响应
3. **中断嵌套处理**：允许高优先级中断打断低优先级中断
4. **现场保护与恢复**：自动或由程序保存/恢复CPU现场
5. **中断向量查找**：根据中断类型号找到中断服务程序入口

## 中断处理过程

1. 中断源发出中断请求
2. CPU判断是否响应（中断允许、优先级）
3. 保护现场（PC、PSW压栈）
4. 关中断、查找中断向量
5. 执行中断服务程序
6. 恢复现场、开中断、中断返回

> 中断系统是现代计算机实现多任务、实时处理的基础。`,
