    question: '什么是中断优先级？为什么要设置优先级？',
    answer: `## 中断优先级

中断优先级是指当多个中断源同时发出中断请求时，CPU响应它们的先后次序。

## 设置优先级的原因

1. **紧急程度不同**：硬件故障比一般I/O更紧急
2. **速度要求不同**：高速设备数据不能等待
3. **重要性不同**：系统时钟、电源故障需优先处理

## 优先级排队方法

### 硬件排队
- **链式排队器**：通过硬件连线决定优先级，离CPU越近优先级越高
- **优先级编码器**：用编码器电路实现优先级判断

### 软件排队
- **查询法**：CPU按优先级顺序查询各中断源状态

## 典型优先级排序（高到低）

1. 电源故障（最高）
2. 自陷（内部中断）
3. 硬件故障
4. 外部中断（高速设备优先）
5. 软件中断（最低）

> 优先级保证了紧急事件能被及时处理。`,
    relatedTopics: ['输入输出系统', '中断系统', '中断嵌套'],
    chapter: '第7章 输入输出系统',
