    question: '中断向量表是如何组织的？它在内存中的位置在哪里？',
    answer: `## 中断向量表

中断向量表是存放所有中断服务程序入口地址的表格，位于内存的固定区域。

## 表的组织（以8086为例）

| 项目 | 说明 |
|------|------|
| 表的位置 | 内存最低端 00000H ~ 003FFH |
| 表的大小 | 1024字节（1KB） |
| 中断数量 | 256个（类型号0-255） |
| 每个向量 | 4字节（2字节IP + 2字节CS） |

## 中断向量表内容

| 中断类型号 | 地址范围 | 用途 |
|-----------|---------|------|
| 0 | 00000-00003 | 除法错误 |
| 1 | 00004-00007 | 单步中断 |
| 8 | 00020-00023 | 定时器中断（IRQ0） |
| 21H | 00084-00087 | DOS系统调用 |

## CPU查找流程

1. 获取中断类型号N
2. 计算地址：N × 4
3. 从该地址读取2字节作为IP
4. 从 N×4+2 读取2字节作为CS
5. 跳转到 CS:IP 执行中断服务程序

## 现代CPU的变化

- 80386+使用**中断描述符表（IDT）**，每个描述符8字节
- 保护模式下IDT可放在内存任意位置（由IDTR寄存器指定）

> 中断向量表是中断系统的核心数据结构。`,
