    id: 'q358',
    keyword: '中断响应',
    question: 'CPU响应中断需要满足哪些条件？响应过程是怎样的？',
    answer: `## 中断响应条件

CPU响应中断需要同时满足以下条件：

1. **有中断请求**：至少一个中断源发出请求信号
2. **CPU允许中断**：中断允许触发器为1（IF=1，开中断状态）
3. **当前指令执行完毕**：CPU在指令周期的最后才会响应
4. **无更高优先级的DMA请求**：DMA优先级高于中断
5. **优先级足够高**：请求中断的优先级高于当前正在处理的中断

## 中断响应过程

1. **关中断**：CPU自动将IF置0，防止响应过程被打断
2. **保护断点**：将当前PC和PSW压入堆栈
3. **获取中断类型号**：从中断控制器读取类型号
4. **查找中断向量**：根据类型号计算中断向量地址
5. **转移控制**：将中断服务程序入口地址装入PC
6. **保护现场**：中断服务程序中保存需要的寄存器
7. **开中断**：允许更高级中断嵌套

## 关键点

- 响应中断的时机是**指令执行完毕**，不是任意时刻
- 响应过程由**硬件自动完成**（关中断、保护断点、获取向量）
- 现场保护由**软件完成**（中断服务程序中 PUSH 指令）

> 中断响应是硬件和软件协同完成的复杂过程。`,
