    id: 'q359',
    keyword: '多重中断',
    question: '多重中断的处理策略是什么？它与单级中断有何区别？',
    answer: `## 多重中断

多重中断是指在处理一个中断的过程中，又响应了新的中断请求，形成中断的嵌套处理。

## 两种处理策略

### 1. 单级中断（不允许嵌套）
- 中断响应后关中断，直到当前中断处理完毕
- 结构简单，但无法及时响应高优先级中断

### 2. 多重中断（允许嵌套）
- 中断服务程序中重新开中断，允许更高级中断打断
- 实时性好，但需要更多栈空间

## 多重中断的实现要点

1. **现场保护后开中断**：保护现场期间关中断，保护完毕后开中断
2. **优先级判别**：只有更高优先级中断才能嵌套
3. **栈管理**：每层中断的现场信息都要入栈，注意栈溢出

## 单级 vs 多重

| 项目 | 单级中断 | 多重中断 |
|------|---------|---------|
| 嵌套 | 不允许 | 允许 |
| 实时性 | 差 | 好 |
| 复杂度 | 简单 | 复杂 |
| 栈需求 | 小 | 大 |

> 现代操作系统普遍采用多重中断机制，保证关键事件的及时处理。`,
