    question: '中断判优有哪些方法？各有什么特点？',
    answer: `## 中断判优方法

当多个中断源同时发出中断请求时，需要按优先级决定响应顺序。

## 硬件判优方法

### 1. 链式排队器
- 中断请求信号通过链式电路依次传递
- 离CPU越近的中断源优先级越高
- 优点：电路简单
- 缺点：优先级固定，链路延迟影响速度

### 2. 优先级编码器
- 使用编码器芯片（如74LS148）
- 多个中断请求同时输入，编码器输出最高优先级的中断类型号
- 优点：响应快
- 缺点：优先级固定

### 3. 可编程中断控制器（PIC）
- 如8259A芯片，支持优先级编程设置
- 可动态调整优先级
- 优点：灵活性强
- 缺点：成本较高

## 软件判优方法

### 查询法
- CPU依次查询各中断源状态
- 先查询的优先级高
- 优点：简单灵活
- 缺点：速度慢

## 对比

| 方法 | 速度 | 灵活性 | 复杂度 |
|------|------|--------|--------|
| 链式 | 中 | 低 | 低 |
| 编码器 | 快 | 低 | 中 |
| PIC | 快 | 高 | 高 |
| 查询法 | 慢 | 高 | 低 |

> 现代PC使用可编程中断控制器（如8259A/APIC）进行中断管理。`,
