    keyword: '向量中断',
    question: '什么是向量中断？它的工作机制是怎样的？',
    answer: `## 向量中断

向量中断是一种中断响应方式，中断源在发出中断请求时，能直接向CPU提供中断类型号（向量地址）。

## 工作机制

1. 中断源发出中断请求信号
2. CPU响应后，中断源通过数据总线发送中断类型号
3. CPU根据类型号在中断向量表中查找入口地址
4. 转去执行中断服务程序

## 向量中断的实现

### 硬件实现
- 每个中断源连接一个向量发生器
- CPU响应中断时发出INTA信号
- 中断源将中断类型号送到数据总线
- CPU读取类型号

### 8259A中断控制器
- 8259A管理8级中断（可级联扩展到64级）
- CPU响应后，8259A发送中断类型号
- 支持多种工作方式（全嵌套、循环优先级等）

## 优点

1. **响应速度快**：硬件直接提供类型号
2. **灵活性高**：可编程设置类型号
3. **支持多中断源**：扩展性好

## 与非向量中断对比

| 项目 | 向量中断 | 非向量中断 |
|------|---------|-----------|
| 类型号 | 硬件提供 | 软件查询 |
| 响应速度 | 快 | 慢 |
| 硬件需求 | 多 | 少 |

> 向量中断是现代计算机的主流中断方式。`,
