    id: 'q370',
    keyword: '单级中断',
    question: '单级中断的工作过程是怎样的？有什么优缺点？',
    answer: `## 单级中断

单级中断是指CPU在执行中断服务程序期间，不允许响应任何新的中断请求。

## 工作过程

1. 中断源发出中断请求
2. CPU响应中断，**自动关中断**（IF=0）
3. 保护断点（PC、PSW入栈）
4. 执行中断服务程序（全程关中断）
5. 恢复现场
6. 中断返回（IRET自动恢复IF=1）

## 特点

- 中断服务程序执行期间**不允许嵌套**
- 简单可靠，不会出现栈溢出
- 但高优先级中断也无法及时响应

## 优点

1. **实现简单**：不需要复杂的优先级管理
2. **栈空间小**：只有一层中断现场
3. **可靠性强**：不会出现嵌套导致的栈溢出

## 缺点

1. **实时性差**：高优先级中断必须等待
2. **响应延迟大**：当前中断处理完才能响应新中断
3. **不适合多任务**：无法处理紧急事件

## 适用场景

- 简单的嵌入式系统
- 中断源数量少
- 对实时性要求不高

## 与多重中断对比

| 项目 | 单级中断 | 多重中断 |
|------|---------|---------|
| 嵌套 | 不允许 | 允许 |
| IF状态 | 全程为0 | 保护现场后置1 |
| 栈深度 | 1层 | N层 |
| 实时性 | 差 | 好 |

> 单级中断是中断处理的基础形式，简单但不灵活。`,
    relatedTopics: ['输入输出系统', '中断系统', '多重中断', '中断嵌套'],
