    keyword: 'DMA与中断对比',
    question: 'DMA方式和程序中断方式有什么区别？',
    answer: `## DMA与中断方式对比

| 对比项 | DMA方式 | 程序中断方式 |
|--------|---------|-------------|
| **数据传输者** | DMA控制器 | CPU |
| **CPU参与** | 仅开始和结束 | 每个数据都参与 |
| **传输单位** | 数据块 | 一个字 |
| **响应时间** | 存储周期级 | 指令周期级 |
| **优先级** | 高于中断 | 低于DMA |
| **中断用途** | 传输结束通知 | 数据传输 |
| **适用设备** | 高速设备 | 中低速设备 |
| **CPU效率** | 高 | 较低 |
| **硬件复杂度** | 高 | 低 |

## 关键区别

### 1. 数据传输执行者
- **中断**：CPU执行中断服务程序完成数据传输
- **DMA**：DMA控制器独立完成数据传输，CPU不参与

### 2. 中断的作用
- **中断方式**：中断用于数据传输（每传一个字中断一次）
- **DMA方式**：中断仅用于传输结束通知（一块数据传输完毕才中断一次）

### 3. 优先级
- DMA优先级**高于**中断
- 因为DMA涉及高速设备，数据不能等待
- DMA请求会延迟中断响应

## 性能对比示例

传输1000个字的数据：
- **中断方式**：1000次中断，CPU开销巨大
- **DMA方式**：1次中断（传输结束），CPU几乎无开销

## 应用场景

| 设备类型 | 推荐方式 | 原因 |
|---------|---------|------|
| 键盘、鼠标 | 中断 | 数据量小，速度慢 |
| 网卡 | DMA | 数据量大，速度高 |
| 硬盘 | DMA | 数据块传输，速度高 |
| 串口 | 中断/DMA | 取决于数据量 |

> DMA方式是高速数据传输的首选方案。`,
    relatedTopics: ['输入输出系统', 'DMA方式', '程序中断', 'I/O控制方式'],
