    question: '什么是SISD架构？传统单处理器属于哪种类型？',
    answer: `## SISD（单指令流单数据流）

SISD是指一次只执行一条指令、处理一个数据的传统计算机体系结构。

## 工作原理

- 一个处理器，一次执行一条指令
- 一条指令处理一个数据
- 严格的顺序执行

## 特点

1. **结构简单**：单个处理器
2. **顺序执行**：指令按序逐条执行
3. **无并行性**（基础层面）

## 性能提升手段

SISD可通过以下方式提升性能：
- 指令流水线（时间重叠）
- Cache缓存（减少访存延迟）
- 主频提升

## 代表系统

- 早期单核CPU（如8086、80486）
- 简单的微控制器

## 与其他架构对比

| 架构 | 指令流 | 数据流 | 典型应用 |
|------|--------|--------|---------|
| SISD | 单 | 单 | 传统单核CPU |
| SIMD | 单 | 多 | 向量处理、GPU |
| MISD | 多 | 单 | 容错系统（罕见） |
| MIMD | 多 | 多 | 多核、多处理器 |

> SISD是最基础的计算机架构，现代CPU通过流水线等技术提升其性能。`,
