    question: '什么是Flynn分类法？它如何分类计算机体系结构？',
    answer: `## Flynn分类法

Flynn分类法由Michael Flynn于1966年提出，根据**指令流**和**数据流**的数量对计算机体系结构进行分类。

## 四种类型

| 类型 | 指令流 | 数据流 | 典型应用 |
|------|--------|--------|---------|
| SISD | 单 | 单 | 传统单核CPU |
| SIMD | 单 | 多 | 向量处理机、GPU |
| MISD | 多 | 单 | 容错系统（罕见） |
| MIMD | 多 | 多 | 多核、多处理器 |

## 分类说明

1. **SISD**：一次一条指令处理一个数据，如8086
2. **SIMD**：一条指令处理多个数据，如向量机、GPU
3. **MISD**：多条指令处理同一数据，如容错系统
4. **MIMD**：多条指令处理多个数据，如多核CPU

## 现代计算机的混合架构

现代CPU通常是多种架构的组合：
- 整体是MIMD（多核）
- 单核内有指令级并行（流水线）
- SIMD扩展指令（SSE/AVX）
- GPU部分是SIMD

> Flynn分类法是理解计算机体系结构的基础框架。`,
