    question: '什么是流水线技术？它如何提高处理器性能？',
    answer: `## 流水线技术

流水线技术将指令执行过程分成多个子过程，每个子过程由不同部件并行完成。

## 基本原理

5级流水线示例：
1. 取指（IF）
2. 译码（ID）
3. 执行（EX）
4. 访存（MEM）
5. 写回（WB）

理想情况下，5条指令在不同阶段同时执行，吞吐率提升约5倍。

## 性能指标

- **吞吐率** = 指令数 / 总时间
- **加速比** = 不用流水线时间 / 用流水线时间
- **效率** = 加速比 / 流水段数

## 流水线类型

1. **指令流水线**：多条指令重叠执行
2. **算术流水线**：运算过程分段
3. **超流水线**：增加流水段数，提高主频

## 流水线冲突

| 类型 | 原因 | 解决方法 |
|------|------|---------|
| 结构冲突 | 资源争用 | 资源重复 |
| 数据冲突 | 数据依赖 | 转发/停顿 |
| 控制冲突 | 分支指令 | 分支预测 |

> 流水线是通过时间重叠实现并行性的经典技术。`,
