    answer: `## 向量指令

向量指令是对整个向量（数组）进行操作的指令，一条指令可处理多个数据。

## 常见向量指令

1. **向量加法**：VADD V1, V2, V3（V1[i] = V2[i] + V3[i]）
2. **向量乘法**：VMUL V1, V2, V3
3. **向量加载**：VLD V1, [addr]
4. **向量存储**：VST V1, [addr]
5. **规约运算**：VDOT（点积）

## 与标量指令的区别

| 对比项 | 向量指令 | 标量指令 |
|--------|---------|---------|
| 操作对象 | 向量（多个数据） | 单个数据 |
| 指令数 | 少（一条指令） | 多（循环多条） |
| 效率 | 高 | 低 |
| 适用 | 数组运算 | 标量运算 |

## 向量指令的优势

1. **减少指令数**：一条指令代替循环
2. **减少控制开销**：无分支、无循环判断
3. **利于流水线**：数据连续，访存规则

## 向量长度寄存器（VLR）

- 控制向量指令处理的元素个数
- 适应不同长度的向量
- 处理剩余元素（向量长度不是寄存器长度整数倍）

> 向量指令是数据级并行的核心，大幅提升数组运算效率。`,
