    answer: `## 多处理器系统

多处理器系统是由多个处理器组成的计算机系统，处理器间通过共享内存或互连网络通信。

## 分类

### 1. 按内存组织分

**共享内存型（UMA/SMP）**：
- 所有处理器共享同一物理内存
- 访存时间一致（UMA）
- 代表：对称多处理（SMP）

**分布式内存型（NUMA/MPP）**：
- 各处理器有本地内存
- 访存时间不一致（NUMA）
- 代表：大规模并行处理（MPP）

### 2. 按耦合度分

- **紧耦合**：共享内存，通信快
- **松耦合**：独立内存，消息通信

## 共享内存型（SMP）

- 各处理器地位平等
- 共享同一内存和I/O
- 通过总线或交叉开关互连

## 分布式内存型（MPP）

- 由大量节点组成
- 每个节点有独立CPU和内存
- 通过高速网络互连

## 多处理器 vs 多计算机

| 对比项 | 多处理器 | 多计算机 |
|--------|---------|---------|
| 内存 | 共享 | 独立 |
| 通信 | 共享变量 | 消息传递 |
| 编程 | 较易（线程） | 较难（MPI） |
| 扩展性 | 有限 | 好 |

> 多处理器系统是高性能计算的重要平台。`,
