    question: '多核处理器的架构是怎样的？它解决了什么问题？',
    answer: `## 多核处理器

多核处理器是在单个芯片上集成多个处理器核心的CPU。

## 架构组成

1. **多个核心**：每个核心有独立的L1 Cache和执行单元
2. **共享L2/L3 Cache**：核心间通过共享缓存通信
3. **共享内存控制器**：统一访问主存
4. **互连结构**：总线、环状或网状互连

## 解决的问题

1. **功耗墙**：单核提升主频导致功耗过高
2. **内存墙**：单核性能提升受内存带宽限制
3. **散热问题**：多核低频比单核高频更易散热
4. **摩尔定律**：增加核心数比提升主频更有效

## 多核架构类型

### 1. 同构多核
- 所有核心结构相同
- 如4个相同的x86核心

### 2. 异构多核
- 不同类型核心组合
- 如CPU+GPU（AMD APU）
- 如大核+小核（ARM big.LITTLE）

## 多核的挑战

1. **编程模型**：需要多线程编程
2. **Cache一致性**：多核Cache数据同步
3. **内存带宽**：多核共享带宽瓶颈
4. **任务调度**：负载均衡

## 多核发展趋势

- 核心数持续增加（4→8→16→64+）
- 异构计算（CPU+GPU+NPU）
- 3D堆叠封装

> 多核是提升CPU性能的主流方向。`,
