    question: '什么是共享内存架构？它有什么优缺点？',
    answer: `## 共享内存架构

共享内存架构是多处理器系统中所有处理器共享同一物理内存的架构。

## 工作方式

- 所有处理器访问同一地址空间
- 通过共享变量通信
- 一个处理器写，其他处理器可见

## 类型

1. **UMA（一致内存访问）**：
   - 所有处理器访存时间相同
   - 对称多处理（SMP）

2. **NUMA（非一致内存访问）**：
   - 各处理器有本地内存
   - 访问本地内存快，远程内存慢

## 优点

1. **编程简单**：共享变量通信，类似单线程
2. **通信效率高**：无需数据拷贝
3. **数据共享方便**：直接访问共享数据

## 缺点

1. **扩展性差**：处理器多时总线成为瓶颈
2. **Cache一致性**：需要维护多Cache一致
3. **同步开销**：需要锁机制保护共享数据

## 共享内存的同步

- **锁（Lock）**：互斥访问共享资源
- **信号量（Semaphore）**：控制资源访问数
- **屏障（Barrier）**：等待所有线程到达

## 编程模型

- **OpenMP**：基于编译指令的并行编程
- **Pthreads**：POSIX线程库
- **Java线程**：语言级多线程

> 共享内存架构编程方便，但扩展性受总线限制。`,
