    answer: `## 静态互连网络

静态互连网络的连接结构固定不变，节点间通过固定的物理链路连接。

## 常见拓扑结构

### 1. 总线结构
- 所有节点连接到一条总线
- 优点：简单、成本低
- 缺点：总线争用、扩展性差
- 适用：小规模系统（SMP）

### 2. 环形结构
- 节点首尾相连成环
- 优点：简单、度数固定为2
- 缺点：平均延迟随节点数增加
- 适用：中等规模系统

### 3. 网格结构
- 节点排列成二维（或三维）网格
- 优点：扩展性好、局部性好
- 缺点：直径较大
- 适用：大规模科学计算

### 4. 超立方体
- N个节点，每个连接log₂N个邻居
- 优点：直径小（logN）、对称
- 缺点：度数随节点数增加
- 适用：中大规模系统

### 5. 树形结构
- 层次化连接
- 优点：层次清晰、寻径简单
- 缺点：根节点瓶颈
- 适用：层次化系统

## 拓扑比较

| 拓扑 | 度 | 直径 | 扩展性 | 成本 |
|------|---|------|--------|------|
| 总线 | 1 | 1 | 差 | 低 |
| 环 | 2 | N/2 | 中 | 低 |
| 网格 | 4 | 2√N | 好 | 中 |
| 超立方体 | logN | logN | 好 | 高 |
| 树 | 1-3 | logN | 中 | 中 |

## 选择原则

- 小规模：总线
- 中规模：环、网格
- 大规模：超立方体、3D网格

> 静态互连网络的拓扑结构决定了并行系统的通信性能。`,
