    id: 'q450',
    keyword: '基准测试',
    question: '什么是基准测试？常见的基准测试程序有哪些？',
    answer: `## 基准测试

基准测试是用标准化的测试程序评估计算机性能的方法。

## 测试程序分类

### 1. 真实程序
- 实际应用软件
- 如：Word、Photoshop
- 最真实但难标准化

### 2. 核心程序
- 实际程序的关键部分
- 如：Photoshop滤镜
- 平衡真实性和标准性

### 3. 小基准程序
- 专门设计的测试程序
- 如：排序、矩阵乘法
- 易于分析但片面

### 4. 合成基准
- 模拟真实程序特征
- 综合多种操作
- 代表性中等

## 常见基准测试

| 基准 | 类型 | 测试内容 |
|------|------|---------|
| SPEC CPU | 核心程序 | CPU整数/浮点 |
| SPECint | 核心 | 整数性能 |
| SPECfp | 核心 | 浮点性能 |
| TPC-C | 真实 | 事务处理 |
| TPC-H | 真实 | 决策支持 |
| STREAM | 小基准 | 内存带宽 |
| LINPACK | 小基准 | 浮点运算 |
| Whetstone | 合成 | 浮点 |
| Dhrystone | 合成 | 整数 |

## 测试方法

1. **编译选项固定**：保证可比性
2. **多次运行取平均**：减少误差
3. **报告配置**：硬件、软件环境
4. **公布源数据**：保证可重现

## 评价指标

- **SPECratio**：被测机/VAX-11/780的比值
- **几何平均**：多个程序综合分

## 注意事项

- 单一基准不代表整体性能
- 不同应用类型需不同基准
- 警惕"基准优化"作弊

> 基准测试为性能对比提供标准化依据，需结合应用选择。`,
